import{_ as l,c as i,o,ag as e}from"./chunks/framework.B1jFR3yW.js";const p=JSON.parse('{"title":"006 集成学习","description":"","frontmatter":{},"headers":[],"relativePath":"python/机器学习/006集成学习.md","filePath":"python/机器学习/006集成学习.md"}'),t={name:"python/机器学习/006集成学习.md"};function r(h,a,n,s,d,u){return o(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="_006-集成学习" tabindex="-1">006 集成学习 <a class="header-anchor" href="#_006-集成学习" aria-label="Permalink to &quot;006 集成学习&quot;">​</a></h1><h2 id="集成学习是什么" tabindex="-1">集成学习是什么 <a class="header-anchor" href="#集成学习是什么" aria-label="Permalink to &quot;集成学习是什么&quot;">​</a></h2><p>集成学习的核心思想是：</p><p>不要只依赖一个模型，而是组合多个模型，让整体效果更稳、更强。</p><h2 id="两大主流方向" tabindex="-1">两大主流方向 <a class="header-anchor" href="#两大主流方向" aria-label="Permalink to &quot;两大主流方向&quot;">​</a></h2><h3 id="bagging" tabindex="-1">Bagging <a class="header-anchor" href="#bagging" aria-label="Permalink to &quot;Bagging&quot;">​</a></h3><p>代表模型：</p><ul><li>随机森林</li></ul><p>思路：</p><ul><li>并行训练多个基模型</li><li>最后投票或平均</li></ul><h3 id="boosting" tabindex="-1">Boosting <a class="header-anchor" href="#boosting" aria-label="Permalink to &quot;Boosting&quot;">​</a></h3><p>代表模型：</p><ul><li>AdaBoost</li><li>GBDT</li><li>XGBoost</li></ul><p>思路：</p><ul><li>后一个模型重点学习前一个模型没学好的地方</li><li>串行提升整体效果</li></ul><h2 id="随机森林" tabindex="-1">随机森林 <a class="header-anchor" href="#随机森林" aria-label="Permalink to &quot;随机森林&quot;">​</a></h2><p>随机森林本质上是多棵决策树的组合。</p><p>它通常比单棵决策树更稳，泛化能力更强。</p><h3 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to &quot;优点&quot;">​</a></h3><ul><li>稳定</li><li>不容易像单棵树那样严重过拟合</li><li>在表格数据任务中很常用</li></ul><h2 id="adaboost" tabindex="-1">AdaBoost <a class="header-anchor" href="#adaboost" aria-label="Permalink to &quot;AdaBoost&quot;">​</a></h2><p>AdaBoost 会不断提升前面分错样本的权重，让后续模型更关注难样本。</p><h2 id="gbdt" tabindex="-1">GBDT <a class="header-anchor" href="#gbdt" aria-label="Permalink to &quot;GBDT&quot;">​</a></h2><p>GBDT 是梯度提升树，属于经典的 Boosting 方法，在传统机器学习里非常重要。</p><h2 id="xgboost" tabindex="-1">XGBoost <a class="header-anchor" href="#xgboost" aria-label="Permalink to &quot;XGBoost&quot;">​</a></h2><p>XGBoost 是工程上很强的树模型提升方案，常用于：</p><ul><li>比赛</li><li>风控</li><li>排序</li><li>表格数据建模</li></ul><h2 id="集成学习的优点" tabindex="-1">集成学习的优点 <a class="header-anchor" href="#集成学习的优点" aria-label="Permalink to &quot;集成学习的优点&quot;">​</a></h2><ul><li>泛化能力通常比单模型更好</li><li>对复杂任务更有表现力</li><li>在结构化数据场景非常强</li></ul><h2 id="集成学习的代价" tabindex="-1">集成学习的代价 <a class="header-anchor" href="#集成学习的代价" aria-label="Permalink to &quot;集成学习的代价&quot;">​</a></h2><ul><li>训练和解释成本更高</li><li>模型更复杂</li><li>调参空间更大</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><p>学集成学习时，先把框架记住：</p><ul><li>决策树是基础</li><li>随机森林属于 Bagging</li><li>AdaBoost / GBDT / XGBoost 属于 Boosting</li><li>表格数据任务里，集成学习经常是主力方法</li></ul>',34)])])}const b=l(t,[["render",r]]);export{p as __pageData,b as default};
